#include "coh_power_join.h"
#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
static unsigned checks;
#define CHECK(x) do{checks++;if(!(x)){fprintf(stderr,"%s:%d: %s\n",__FILE__,__LINE__,#x);exit(2);}}while(0)
typedef struct {FILE*file;EVP_MD_CTX*digest;unsigned reads,cancels,fail_at,cancel_at;} Provider;
static CohStatus read_at(void*ctx,uint32_t at,uint8_t*out,size_t n){Provider*p=ctx;p->reads++;if(p->fail_at&&p->reads==p->fail_at)return COH_IO;if(fseek(p->file,(long)at,SEEK_SET)||fread(out,1,n,p->file)!=n)return COH_IO;return COH_OK;}
static CohStatus begin(void*ctx){Provider*p=ctx;return EVP_DigestInit_ex(p->digest,EVP_sha256(),NULL)==1?COH_OK:COH_IO;}
static CohStatus update(void*ctx,CohBytes b){Provider*p=ctx;return EVP_DigestUpdate(p->digest,b.data,b.size)==1?COH_OK:COH_IO;}
static CohStatus finish(void*ctx,uint8_t out[32]){Provider*p=ctx;unsigned n;return EVP_DigestFinal_ex(p->digest,out,&n)==1&&n==32?COH_OK:COH_IO;}
static void abort_digest(void*ctx){(void)ctx;}
static int cancelled(void*ctx){Provider*p=ctx;p->cancels++;return p->cancel_at&&p->cancels==p->cancel_at;}
static CohStatus sha256(void*ctx,CohBytes b,uint8_t out[32]){(void)ctx;unsigned n;return EVP_Digest(b.data,b.size,out,&n,EVP_sha256(),NULL)==1&&n==32?COH_OK:COH_IO;}
static uint32_t word(FILE*f){uint8_t b[4];CHECK(fread(b,1,4,f)==4);return(uint32_t)b[0]|(uint32_t)b[1]<<8|(uint32_t)b[2]<<16|(uint32_t)b[3]<<24;}
static CohBytes load(const char*path){FILE*f=fopen(path,"rb");CHECK(f);CHECK(!fseek(f,0,SEEK_END));long n=ftell(f);CHECK(n>0);CHECK(!fseek(f,0,SEEK_SET));uint8_t*b=malloc((size_t)n);CHECK(b);CHECK(fread(b,1,(size_t)n,f)==(size_t)n);CHECK(!fclose(f));return(CohBytes){b,(size_t)n};}
static CohPowerCategoryDictionary*cats;static CohPowerSetDictionary*sets;static CohPowerStreamDictionary*pows;static CohPowerJoin*out,*saved;static CohPowerJoinWorkspace*workspace;
int main(int argc,char**argv){CHECK(argc==6);CohBytes catbytes=load(argv[1]),setbytes=load(argv[2]);cats=calloc(1,sizeof(*cats));sets=calloc(1,sizeof(*sets));pows=calloc(1,sizeof(*pows));out=malloc(sizeof(*out));saved=malloc(sizeof(*saved));workspace=malloc(sizeof(*workspace));CHECK(cats&&sets&&pows&&out&&saved&&workspace);memset(out,0x5a,sizeof(*out));*saved=*out;CohCostumeImportDigest digest={0};digest.sha256=sha256;uint8_t hash[32];CHECK(sha256(NULL,catbytes,hash)==COH_OK);CohPowerCategoryWorkspace*cw=malloc(sizeof(*cw));CHECK(cw);CHECK(coh_power_categories_read(catbytes,1,hash,&digest,cats,cw,COH_CATEGORY_RAM_MAX,0)==COH_OK);free(cw);free((void*)catbytes.data);
 CHECK(sha256(NULL,setbytes,hash)==COH_OK);CohPowerSetWorkspace*sw=malloc(sizeof(*sw));CHECK(sw);CHECK(coh_power_sets_read(setbytes,2,hash,&digest,sets,sw,COH_POWER_SET_RAM_MAX,0)==COH_OK);free(sw);
 Provider provider={0};provider.file=fopen(argv[3],"rb");provider.digest=EVP_MD_CTX_new();CHECK(provider.file&&provider.digest);CHECK(!fseek(provider.file,0,SEEK_END));long size=ftell(provider.file);CHECK(size>0&&size<=COH_POWER_STREAM_MAX);CHECK(!fseek(provider.file,0,SEEK_SET));CHECK(begin(&provider)==COH_OK);uint8_t buffer[4096];size_t n;while((n=fread(buffer,1,sizeof(buffer),provider.file))!=0)CHECK(update(&provider,(CohBytes){buffer,n})==COH_OK);CHECK(!ferror(provider.file));CHECK(finish(&provider,hash)==COH_OK);CohPowerStreamProvider pp={&provider,sizeof(provider),16384,(uint32_t)size,3,read_at,begin,update,finish,abort_digest,cancelled};CohPowerStreamWorkspace*pw=malloc(sizeof(*pw));CHECK(pw);CHECK(coh_power_stream_read(&pp,hash,pows,pw,COH_POWER_STREAM_RAM_MAX,0)==COH_OK);free(pw);
 provider.reads=provider.cancels=0;CohStatus status=coh_power_join_prepare(cats,sets,pows,out,workspace,COH_POWER_JOIN_RAM_MAX,0);FILE*expected=fopen(argv[4],"rb");CHECK(expected);unsigned expected_status=word(expected);CHECK((unsigned)status==expected_status);
 if(status==COH_OK){CHECK(out->complete_forward_join&&out->parent_projection&&!out->runtime_generation&&!out->actor_authority);CHECK(out->category_count==cats->count&&out->set_count==sets->count&&out->power_count==pows->count);CHECK(out->category_reference_count==word(expected));CHECK(out->power_reference_count==word(expected));CHECK(out->alternate_name_count==word(expected));for(unsigned i=0;i<out->category_reference_count;i++)CHECK(out->category_sets[i]==word(expected));for(unsigned i=0;i<sets->count;i++){uint32_t count=word(expected),parent=word(expected);CHECK(out->set_links[i].count==count&&out->set_links[i].parent_category==parent);for(unsigned j=0;j<count;j++){CohPowerJoinReference r=out->power_links[out->set_links[i].first+j];CHECK(r.declared_power==word(expected));CHECK(r.resolved_power==word(expected));}}for(unsigned i=0;i<pows->count;i++)CHECK(out->power_parent_sets[i]==word(expected));CHECK(word(expected)==UINT32_C(0xabcdef01));CHECK(fgetc(expected)==EOF);*saved=*out;
 }else CHECK(!memcmp(out,saved,sizeof(*out)));
 CHECK(!fclose(expected));unsigned baseline_reads=provider.reads,baseline_cancels=provider.cancels;provider.reads=provider.cancels=0;
 /* Failure is before provider interaction and preserves the previous owner. */
 CHECK(coh_power_join_prepare(cats,sets,pows,out,workspace,1,0)==COH_LIMIT);CHECK(!provider.reads&&!provider.cancels&&!memcmp(out,saved,sizeof(*out)));
 CHECK(coh_power_join_prepare(cats,sets,pows,out,workspace,COH_POWER_JOIN_RAM_MAX,COH_POWER_JOIN_RAM_MAX)==COH_LIMIT);CHECK(!provider.reads&&!provider.cancels&&!memcmp(out,saved,sizeof(*out)));
 CHECK(coh_power_join_prepare(cats,sets,pows,out,(CohPowerJoinWorkspace*)out,COH_POWER_JOIN_RAM_MAX,0)==COH_INVALID);CHECK(!provider.reads&&!provider.cancels&&!memcmp(out,saved,sizeof(*out)));
 sets->source_constructor_accepted=0;CHECK(coh_power_join_prepare(cats,sets,pows,out,workspace,COH_POWER_JOIN_RAM_MAX,0)==COH_STATE);sets->source_constructor_accepted=1;CHECK(!provider.reads&&!provider.cancels&&!memcmp(out,saved,sizeof(*out)));
 pows->duplicate_count=1;CHECK(coh_power_join_prepare(cats,sets,pows,out,workspace,COH_POWER_JOIN_RAM_MAX,0)==COH_STATE);pows->duplicate_count=0;CHECK(!provider.reads&&!provider.cancels&&!memcmp(out,saved,sizeof(*out)));
 if(baseline_reads){unsigned steps[]={1,2,baseline_reads/2,baseline_reads};for(unsigned i=0;i<4;i++)if(steps[i]){provider.reads=provider.cancels=0;provider.fail_at=steps[i];CHECK(coh_power_join_prepare(cats,sets,pows,out,workspace,COH_POWER_JOIN_RAM_MAX,0)==COH_IO);CHECK(!memcmp(out,saved,sizeof(*out)));}provider.fail_at=0;}
 if(baseline_cancels){unsigned steps[]={1,2,baseline_cancels/2,baseline_cancels};for(unsigned i=0;i<4;i++)if(steps[i]){provider.reads=provider.cancels=0;provider.cancel_at=steps[i];CHECK(coh_power_join_prepare(cats,sets,pows,out,workspace,COH_POWER_JOIN_RAM_MAX,0)==COH_CANCELLED);CHECK(!memcmp(out,saved,sizeof(*out)));}provider.cancel_at=0;}
 CHECK(!fclose(provider.file));EVP_MD_CTX_free(provider.digest);free((void*)setbytes.data);printf("{\"checks\":%u,\"join_status\":%u,\"category_rows\":%u,\"allocated_sets\":%u,\"allocated_powers\":%u,\"provider_name_reads\":%u,\"provider_cancel_boundaries\":%u,\"owner_bytes\":%zu,\"workspace_bytes\":%zu}\n",checks,(unsigned)status,cats->count,sets->count,pows->count,baseline_reads,baseline_cancels,sizeof(*out),sizeof(*workspace));free(cats);free(sets);free(pows);free(out);free(saved);free(workspace);return 0;}
